function rfdude_pll_validate_configuration(config_s, base_directory)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Validate generated runs before analysis or file creation.
p=config_s.pll_inputs_s;
o=config_s.run_options_s;
[defaults,~]=rfdude_pll_configuration();
names=fieldnames(defaults.pll_inputs_s);
for k=1:numel(names)
    name=names{k};
    if ~isfield(p,name)
        error('Missing PLL input: %s',name);
    end
    value=p.(name);
    if ischar(defaults.pll_inputs_s.(name))
        if ~ischar(value) || isempty(value) || ~isrow(value) || any(value==10 | value==13)
            error('%s must be a nonempty single-line filename',name);
        end
    elseif strcmp(name,'pn_ylimits')
        validateattributes(value,{'numeric'},{'vector','numel',2,'real','finite'},'',name);
        if value(1)>=value(2)
            error('pn_ylimits must be increasing');
        end
    else
        validateattributes(value,{'numeric','logical'},{'scalar','real'},'',name);
        if ~any(strcmp(name,{'transient_nl_fvco_min_Hz','transient_nl_fvco_max_Hz'}))
            validateattributes(value,{'numeric','logical'},{'finite'},'',name);
        elseif isnan(value)
            error('%s cannot be NaN',name);
        end
        if strncmp(name,'b',1) || strncmp(name,'filter_override',15)
            validateattributes(value,{'numeric','logical'},{'binary'},'',name);
        end
    end
end
positive={'fout_desired_Hz','mult','Fref_Hz','F_tcxo_Hz','Kphi_A_cycle', ...
    'BW_desired_Hz','ATTEN_dB','Ftcxo_ref_offset_Hz','Fvco_ref_offset_Hz', ...
    'fstart_main_Hz','fstop_main_Hz'};
if ~p.bUseVCOFromFile
    positive{end+1}='Kvco_Hz_volt';
end
if p.filter_override
    positive=[positive {'CC1','CC2','RR2','CC3','RR3'}];
elseif p.filter_override_3rdpole_only
    positive=[positive {'CC3','RR3'}];
end
for k=1:numel(positive)
    validateattributes(p.(positive{k}),{'numeric'},{'positive'},'',positive{k});
end
validateattributes(p.PM_desired_deg,{'numeric'},{'>',0,'<',90},'','PM_desired_deg');
validateattributes(p.fsweep_main_pts,{'numeric'},{'integer','>=',2},'','fsweep_main_pts');
if p.fstart_main_Hz>=p.fstop_main_Hz
    error('Frequency-grid stop must exceed start');
end
if p.filter_override && p.filter_override_3rdpole_only
    error('Choose full override OR third-pole-only override');
end
if p.PM_desired_deg+180*p.BW_desired_Hz/p.Fref_Hz>=90
    error('Requested bandwidth/phase margin exceeds the synthesis phase-delay limit');
end
if p.bDoTransient || p.bDoTransientNonlinear
    validateattributes(p.transient_tmax_s,{'numeric'},{'positive'},'','transient_tmax_s');
    validateattributes(p.transient_ftol_Hz,{'numeric'},{'positive'},'','transient_ftol_Hz');
end
if p.bDoTransient
    validateattributes(p.transient_points,{'numeric'},{'integer','>=',2},'','transient_points');
end
if p.bDoTransientNonlinear
    validateattributes(p.transient_nl_steps_per_ref,{'numeric'}, ...
        {'integer','>=',10},'','transient_nl_steps_per_ref');
    target=p.fout_desired_Hz/p.mult;
    if p.transient_nl_fvco_min_Hz>=p.transient_nl_fvco_max_Hz || ...
            target<p.transient_nl_fvco_min_Hz || target>p.transient_nl_fvco_max_Hz || ...
            target+p.transient_delta_f_Hz<=0
        error('Nonlinear VCO limits must contain the target; initial frequency must be positive');
    end
end
for name={'bRunSweep','bShowCorePlots','bEnableDataViewer','bOverwriteResults'}
    validateattributes(o.(name{1}),{'numeric','logical'},{'scalar','binary'},'',name{1});
end
validateattributes(o.integration_lower_Hz,{'numeric'}, ...
    {'scalar','real','finite','>=',p.fstart_main_Hz},'','integration_lower_Hz');
validateattributes(o.integration_upper_Hz,{'numeric'}, ...
    {'scalar','real','finite','<=',p.fstop_main_Hz,'>',o.integration_lower_Hz},'','integration_upper_Hz');
validateattributes(o.noise_offsets_Hz,{'numeric'}, ...
    {'vector','real','finite','nonempty','>=',p.fstart_main_Hz,'<=',p.fstop_main_Hz},'','noise_offsets_Hz');
x=logspace(log10(p.fstart_main_Hz),log10(p.fstop_main_Hz), ...
    1+50*(log10(p.fstop_main_Hz)-log10(p.fstart_main_Hz)));
if sum(x>=o.integration_lower_Hz & x<=o.integration_upper_Hz)<2
    error('Integration limits must contain at least two resampled noise points');
end
allowed={'BW_desired_Hz','PM_desired_deg','Fref_Hz','Kphi_A_cycle','fout_desired_Hz'};
if ~ischar(o.sweep_parameter) || ~any(strcmp(o.sweep_parameter,allowed))
    error('Unsupported design-target sweep parameter');
end
validateattributes(o.sweep_values,{'numeric'},{'vector','real','finite','nonempty'},'','sweep_values');
if o.bRunSweep
    if numel(unique(o.sweep_values))~=numel(o.sweep_values)
        error('Sweep values must be distinct');
    end
    for k=1:numel(o.sweep_values)
        case_config=config_s;
        case_config.pll_inputs_s.(o.sweep_parameter)=o.sweep_values(k);
        case_config.run_options_s.bRunSweep=false;
        rfdude_pll_validate_configuration(case_config,base_directory);
    end
    if p.filter_override && any(strcmp(o.sweep_parameter,{'BW_desired_Hz','PM_desired_deg'}))
        error('A full filter override makes a bandwidth/phase-margin target sweep ineffective');
    end
end
[~,basename,extension]=fileparts(p.def_filename);
if ~strcmpi(extension,'.mat') || isempty(regexp(basename,'^[A-Za-z_][A-Za-z0-9_-]*$','once'))
    error('Results filename must have a simple basename (letters, digits, _ or -) and .mat extension');
end
for source={'TCXO','VCO'}
    kind=source{1};
    if ~p.(['bUse' kind 'FromFile'])
        continue;
    end
    if strcmp(kind,'VCO') && isfield(o,'vco_profile_s')
        [data.pn_struct,~]=select_pn_profile(o.vco_profile_s, ...
            p.fout_desired_Hz/p.mult,'interpolate');
    else
        filename=p.(['File' kind]);
        if ~is_absolute(filename)
            filename=fullfile(base_directory,filename);
        end
        data=load(filename,'pn_struct');
        if ~isfield(data,'pn_struct')
            error('%s file must contain pn_struct',kind);
        end
    end
    s=data.pn_struct;
    required={'f','n','fc'};
    if strcmp(kind,'VCO')
        required=[required {'kvco','name','comment','clock'}];
    end
    for k=1:numel(required)
        if ~isfield(s,required{k})
            error('%s pn_struct lacks %s',kind,required{k});
        end
    end
    validateattributes(s.f,{'numeric'},{'row','real','finite','positive','nonempty'});
    validateattributes(s.n,{'numeric'},{'row','real','finite','numel',numel(s.f)});
    if numel(s.f)<2 || any(diff(s.f)<=0)
        error('%s noise offsets must be strictly increasing with at least two points',kind);
    end
    validateattributes(s.fc,{'numeric'},{'scalar','real','finite','positive'});
    if strcmp(kind,'VCO')
        validateattributes(s.kvco,{'numeric'},{'scalar','real','finite','positive'});
    end
end
if isfield(o,'vco_profile_s') && ~p.bUseVCOFromFile
    error('vco_profile_s requires bUseVCOFromFile=1; otherwise the profile would be ignored.');
end
end

function yes=is_absolute(filename)
yes=filename(1)==filesep || ~isempty(regexp(filename,'^[A-Za-z]:[\\/]','once'));
end
